// src/middleware/otherFunc.ts
var import_obsidian = require("obsidian");

// src/controllers/searchData.ts
var getAdditionalData = async (option, categoriName) => {
  const filePath = `${MainPlugin.instance.dbPath}/${option}.json`;
  try {
    const file = await MainPlugin.instance.app.vault.adapter.read(filePath);
    if (categoriName === "income_plan" || categoriName === "expenditure_plan") {
      const jsonData = JSON.parse(file)[option][categoriName];
      const data = {
        jsonData,
        status: "success"
      };
      return data;
    } else if (option === "accounts") {
      const jsonData = JSON.parse(file)[option];
      const data = {
        jsonData,
        status: "success"
      };
      return data;
    } else {
      return { status: "error", error: new Error("Invalid option provided") };
    }
  } catch (error) {
    return { status: "error", error: error instanceof Error ? error : new Error(String(error)) };
  }
};
var getMainData = async (option) => {
  const { selectedYear, selectedMonth } = stateManager();
  const { year: year2, month } = selectedYear && selectedMonth ? { year: selectedYear, month: selectedMonth } : getDate();
  const filePath = `${MainPlugin.instance.dbPath}/${year2}.json`;
  try {
    const file = await MainPlugin.instance.app.vault.adapter.read(filePath);
    const jsonData = JSON.parse(file).months[month][option];
    const data = {
      jsonData,
      status: "success"
    };
    return data;
  } catch (error) {
    return { status: "error", error: error instanceof Error ? error : new Error(String(error)) };
  }
};
var getAllFile = async (option) => {
  const filePath = `${MainPlugin.instance.dbPath}/${option}.json`;
  try {
    const file = await MainPlugin.instance.app.vault.adapter.read(filePath);
    const jsonData = JSON.parse(file);
    return { status: "success", json: jsonData };
  } catch (error) {
    return { status: "error", error: error instanceof Error ? error : new Error(String(error)) };
  }
};
var searchElementById = async (id, modifier) => {
  const sourceMap = {
    history: () => getMainData("history"),
    accounts: () => getAdditionalData("accounts"),
    expense: () => getAdditionalData("categories", "expenditure_plan"),
    income: () => getAdditionalData("categories", "income_plan")
  };
  try {
    const loader = sourceMap[modifier];
    if (!loader)
      return { status: "error", error: new Error("Element not found") };
    const result = await loader();
    if (result.status === "error")
      return { status: "error", error: result.error };
    const item = result.jsonData.find((item2) => item2.id === id);
    if (item === void 0)
      return { status: "error", error: new Error("Item is undefined") };
    const dataItem = {
      item,
      status: "success"
    };
    return dataItem;
  } catch (err) {
    return { status: "error", error: err instanceof Error ? err : new Error(String(err)) };
  }
};
var searchHistory = async (inputValue) => {
  try {
    const search = inputValue.toLowerCase();
    const [
      history,
      expenditure,
      income,
      bills
    ] = await Promise.all([
      getMainData("history"),
      getAdditionalData("categories", "expenditure_plan"),
      getAdditionalData("categories", "income_plan"),
      getAdditionalData("accounts")
    ]);
    if (expenditure.status === "error" || income.status === "error" || bills.status === "error" || history.status === "error") {
      return { status: "error", error: new Error("Failed to load data for search") };
    }
    const additionalData = [
      ...expenditure.jsonData,
      ...income.jsonData,
      ...bills.jsonData
    ];
    const matchedAdditionalIds = additionalData.filter((item) => "name" in item && item.name.toLowerCase().includes(search)).map((item) => item.id);
    const filteredHistory = history.jsonData.filter((item) => {
      var _a, _b, _c, _d;
      const baseMatch = ((_a = item.type) == null ? void 0 : _a.toLowerCase().includes(search)) || item.amount.toString().includes(inputValue) || ((_b = item.comment) == null ? void 0 : _b.toLowerCase().includes(search));
      if (matchedAdditionalIds.length === 0) {
        return baseMatch;
      }
      return baseMatch || ((_c = item.bill) == null ? void 0 : _c.id) && matchedAdditionalIds.includes(item.bill.id) || ((_d = item.category) == null ? void 0 : _d.id) && matchedAdditionalIds.includes(item.category.id);
    });
    return {
      status: "success",
      jsonData: filteredHistory.length ? filteredHistory : []
    };
  } catch (err) {
    return { status: "error", error: err instanceof Error ? err : new Error(String(err)) };
  }
};

// src/middleware/otherFunc.ts
var popularCodes = ["USD", "EUR", "RUB", "KZT", "UZS"];
var generateUUID = () => {
  return crypto.randomUUID();
};
var getDate = () => {
  import_obsidian.moment.locale("en");
  const now = (0, import_obsidian.moment)();
  return {
    now,
    year: now.format("YYYY"),
    month: now.format("M")
  };
};
var getCurrencyGroups = () => {
  const all = Object.entries(currencies_default).map(([code, info]) => ({
    code,
    name: info.name || code,
    symbol: info.symbol || info.symbolNative
  }));
  const popularCurrencies = all.filter((cur) => popularCodes.includes(cur.code));
  const otherCurrencies = all.filter((cur) => !popularCodes.includes(cur.code));
  return { popularCurrencies, otherCurrencies };
};
function fillMonthDates(selectEl, oldDate) {
  const dayNames = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
  const monthNames = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December"
  ];
  const { selectedYear, selectedMonth } = stateManager();
  if (selectedYear === null && selectedMonth === null) {
    const today = new Date();
    const year2 = today.getFullYear();
    const month = today.getMonth();
    const daysInMonth = new Date(year2, month + 1, 0).getDate();
    for (let d = daysInMonth; d >= 1; d--) {
      const date = new Date(year2, month, d);
      const day = date.getDate();
      const weekday = dayNames[date.getDay()];
      const monthName = monthNames[month];
      let label = `${day} ${monthName}, ${weekday}`;
      const diff = Math.floor((date.getTime() - today.getTime()) / (1e3 * 60 * 60 * 24));
      if (diff === -1)
        label = `Today, ${label}`;
      else if (diff === 0)
        label = `Tomorrow, ${label}`;
      else if (diff === 1)
        label = `The day after tomorrow, ${label}`;
      else if (diff === -2)
        label = `Yesterday, ${label}`;
      else if (diff === -3)
        label = `The day before yesterday, ${label}`;
      const value = `${year2}-${String(month + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
      const option = selectEl.createEl("option", {
        text: label,
        attr: { value }
      });
      if (value === oldDate)
        option.selected = true;
      else if (diff === -1)
        option.selected = true;
    }
  } else {
    const monthIndex = Number(selectedMonth) - 1;
    if (isNaN(monthIndex) || monthIndex < 0 || monthIndex > 11) {
      throw new Error("Invalid month");
    }
    const year2 = Number(selectedYear);
    const month = monthIndex;
    const daysInMonth = new Date(year2, month + 1, 0).getDate();
    for (let d = daysInMonth; d >= 1; d--) {
      const date = new Date(year2, month, d);
      const day = date.getDate();
      const weekday = dayNames[date.getDay()];
      const monthName = monthNames[month];
      const label = `${day} ${monthName}, ${weekday}`;
      const value = `${year2}-${String(month + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
      selectEl.createEl("option", {
        text: label,
        attr: { value }
      });
    }
    selectEl.createEl("option", {
      text: "Select a date",
      attr: {
        value: "",
        selected: "",
        disabled: "",
        hidden: ""
      }
    });
  }
}
function selectRelativeDate(selectEl, offset) {
  const now = new Date();
  const target = new Date(now.getFullYear(), now.getMonth(), now.getDate() + offset);
  const targetValue = `${target.getFullYear()}-${String(target.getMonth() + 1).padStart(2, "0")}-${String(target.getDate()).padStart(2, "0")}`;
  const option = Array.from(selectEl.options).find((opt) => opt.value === targetValue);
  if (option) {
    selectEl.value = targetValue;
  }
}
function checkExpenceOrIncome(amount, type) {
  const bigAmount = new big_default(amount);
  if (type === "expense") {
    return `- ${formatNumbers(bigAmount.toString())}`;
  } else if (type === "income") {
    return `+ ${formatNumbers(bigAmount.toString())}`;
  } else {
    return "Error";
  }
}
function SummarizingDataForTheDay(obj) {
  let expense = new big_default(0);
  let income = new big_default(0);
  obj.forEach((e) => {
    if (e.type === "expense") {
      expense = expense.plus(new big_default(e.amount));
    } else if (e.type === "income") {
      income = income.plus(new big_default(e.amount));
    } else {
      console.error("Invalid type:", e.type);
    }
  });
  if (expense.eq(0)) {
    return `+${formatNumbers(income.toString())}`;
  } else if (income.eq(0)) {
    return `-${formatNumbers(expense.toString())}`;
  } else {
    return `-${formatNumbers(expense.toString())} +${formatNumbers(income.toString())}`;
  }
}
function SummarizingData(obj) {
  if (!obj)
    return new big_default(0);
  if (obj) {
    const arr = obj;
    return arr.reduce((sum, e) => {
      return sum.plus(new big_default(e.amount));
    }, new big_default(0));
  }
  return new big_default(0);
}
function SummarizingDataForTheTrueBills(obj) {
  if (!obj)
    return new big_default(0);
  return obj.reduce((sum, e) => {
    if (e.generalBalance) {
      return sum.plus(new big_default(e.balance));
    }
    return sum;
  }, new big_default(0));
}
function SummarizingDataForTheFalseBills(obj) {
  if (!obj)
    return new big_default(0);
  return obj.reduce((sum, e) => {
    if (!e.generalBalance) {
      return sum.plus(new big_default(e.balance));
    }
    return sum;
  }, new big_default(0));
}
function divideByRemainingDays(amount) {
  const today = new Date();
  const year2 = today.getFullYear();
  const month = today.getMonth();
  const daysInMonth = new Date(year2, month + 1, 0).getDate();
  const currentDay = today.getDate();
  const remainingDays = daysInMonth - currentDay + 1;
  const result = new big_default(amount).div(remainingDays);
  return result.round(0, 0).toNumber();
}
function getCurrencySymbol(code) {
  const currency = currencies_default[code];
  return currency ? currency.symbol || currency.symbolNative || code : code;
}
function switchBalanceLine(billsInfo, expenditurePlanInfo) {
  const fullSum = Number(SummarizingDataForTheTrueBills(billsInfo)) + Number(SummarizingData(expenditurePlanInfo));
  const percent = Number(SummarizingData(expenditurePlanInfo)) / fullSum * 100;
  if (Number(SummarizingData(expenditurePlanInfo)) <= fullSum) {
    return 100 - percent;
  } else if (percent === 0) {
    return 100;
  } else {
    return percent;
  }
}
function humanizeDate(dateStr) {
  const [year2, month, day] = dateStr.split("-").map(Number);
  const date = new Date(year2, month - 1, day);
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const diffDays = Math.round(
    (today.getTime() - date.getTime()) / (1e3 * 60 * 60 * 24)
  );
  const weekdays = [
    "Sunday",
    "Monday",
    "Tuesday",
    "Wednesday",
    "Thursday",
    "Friday",
    "Saturday"
  ];
  const months = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December"
  ];
  let prefix = "";
  if (diffDays === 0)
    prefix = "Today";
  else if (diffDays === 1)
    prefix = "Yesterday";
  else if (diffDays === -1)
    prefix = "Tomorrow";
  else if (diffDays === 2)
    prefix = "The day before yesterday";
  else if (diffDays === -2)
    prefix = "The day after tomorrow";
  const currentYear = today.getFullYear();
  const showYear = date.getFullYear() !== currentYear;
  const formattedDate = showYear ? `${months[date.getMonth()]} ${date.getDate()}, ${date.getFullYear()}, ${weekdays[date.getDay()]}` : `${months[date.getMonth()]} ${date.getDate()}, ${weekdays[date.getDay()]}`;
  return prefix ? `${prefix}, ${formattedDate}` : formattedDate;
}
async function IncomeAndExpensesForTheMonth(month, year2, div) {
  const allData = await getAllFile(year2);
  if (allData.status === "error") {
    new import_obsidian.Notice(allData.error.message);
    console.error(allData.error);
    return;
  }
  const totalExpense = SummarizingData(allData.json.months[month].expenditure_plan);
  const totalIncome = SummarizingData(allData.json.months[month].income_plan);
  if (totalIncome.gte(totalExpense)) {
    div.createEl("span", {
      text: `-${formatNumbers(totalExpense.toString())}`,
      cls: "expense-all-month-success"
    });
    div.createEl("span", {
      text: `+${formatNumbers(totalIncome.toString())}`,
      cls: "income-all-month"
    });
  } else {
    div.createEl("span", {
      text: `-${formatNumbers(totalExpense.toString())}`,
      cls: "expense-all-month-failure"
    });
    div.createEl("span", {
      text: `+${formatNumbers(totalIncome.toString())}`,
      cls: "income-all-month"
    });
  }
}
async function TheSumOfExpensesAndIncomeForTheYear(year2) {
  const allData = await getAllFile(year2);
  if (allData.status === "error") {
    new import_obsidian.Notice(allData.error.message);
    console.error(allData.error);
    return;
  }
  let totalExpense = new big_default(0);
  let totalIncome = new big_default(0);
  for (const month in allData.json.months) {
    totalExpense = totalExpense.plus(SummarizingData(allData.json.months[month].expenditure_plan));
    totalIncome = totalIncome.plus(SummarizingData(allData.json.months[month].income_plan));
  }
  return `-${formatNumbers(totalExpense.toString())} +${formatNumbers(totalIncome.toString())}`;
}
function getLocalTimeISO() {
  const d = new Date();
  d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
  return d.toISOString().split("T")[1].split(".")[0];
}
var mergeCategoriesData = (additionPlan, mainPlan) => {
  if (!additionPlan || !mainPlan)
    return [];
  return mainPlan.map((item) => {
    const category = additionPlan.find((c) => c.id === item.id);
    if (!category)
      return item;
    return {
      ...category,
      amount: item.amount
    };
  });
};
function formatNumbers(input) {
  return input.replace(/\d+(\.\d+)?/g, (num) => {
    const [integerPart, decimalPart] = num.split(".");
    const formattedInt = integerPart.replace(
      /\B(?=(\d{3})+(?!\d))/g,
      " "
    );
    return decimalPart ? `${formattedInt}.${decimalPart}` : formattedInt;
  });
}

