var checkBill = async (data, oldData) => {
  const bills = await getAdditionalData("accounts");
  if (bills.status === "error")
    return { status: "error", error: bills.error };
  const bill = bills.jsonData.find((b) => b.id === data.bill.id);
  if (!bill) {
    return { status: "error", error: new Error(`Bill ${data.bill.id} not found`) };
  }
  const currentBalance = oldData ? new big_default(bill.balance).plus(oldData.amount) : new big_default(bill.balance);
  if (new big_default(data.amount).gte(currentBalance)) {
    return { status: "error", error: new Error(`On bill ${bill.name} insufficient funds`) };
  }
  return { status: "success" };
};
