var transferBetweenBills = async (data) => {
  if (data.fromBillId === data.toBillId) {
    return { status: "error", error: new Error("Cannot transfer to the same bill") };
  }
  const bills = await getAllFile("accounts");
  if (bills.status === "error")
    return { status: "error", error: bills.error };
  const fromBill = bills.json.accounts.find((b) => b.id === data.fromBillId);
  const toBill = bills.json.accounts.find((b) => b.id === data.toBillId);
  if (!fromBill || !toBill) {
    return { status: "error", error: new Error("One or both bills not found") };
  }
  const fromBalance = new big_default(fromBill.balance);
  const toBalance = new big_default(toBill.balance);
  let debit;
  let credit;
  if (data.type === "same-currency") {
    debit = new big_default(data.amount);
    credit = debit;
  } else {
    debit = new big_default(data.sourceAmount);
    credit = new big_default(data.targetAmount);
  }
  if (debit.gt(fromBalance)) {
    return { status: "error", error: new Error(`Insufficient funds in bill ${fromBill.name}`) };
  }
  const newFromBalance = fromBalance.minus(debit);
  const newToBalance = toBalance.plus(credit);
  const newBills = bills.json.accounts.map((bill) => {
    if (bill.id === fromBill.id) {
      return { ...bill, balance: newFromBalance.toFixed(2) };
    }
    if (bill.id === toBill.id) {
      return { ...bill, balance: newToBalance.toFixed(2) };
    }
    return bill;
  });
  bills.json.accounts = newBills;
  try {
    await updateFile("accounts", bills.json);
    return { status: "success" };
  } catch (error) {
    return { status: "error", error: error instanceof Error ? error : new Error(`Error tranfer berween bills: ${String(error)}`) };
  }
};

// src/controllers/editingData.ts
var editingJsonToHistory = async (data, oldData) => {
  if (data.type === "expense") {
    const resultCheckBill = await checkBill(data, oldData);
    if (resultCheckBill.status === "error")
      return { status: "error", error: resultCheckBill.error };
  }
  const { selectedYear, selectedMonth } = stateManager();
  const { year: year2, month } = selectedYear && selectedMonth ? { year: selectedYear, month: selectedMonth } : getDate();
  if (data.type === "expense") {
    const result = await expenditureTransaction(data, "edit", oldData);
    if (result.status === "error")
      return { status: "error", error: result.error };
  } else if (data.type === "income") {
    const result = await incomeTransaction(data, "edit", oldData);
    if (result.status === "error")
      return { status: "error", error: result.error };
  } else {
    return { status: "error", error: new Error("The specified type is not suitable") };
  }
  const allData = await getAllFile(year2);
  if (allData.status === "error")
    return { status: "error", error: allData.error };
  try {
    allData.json.months[month].history = allData.json.months[month].history.map((item) => item.id === data.id ? { ...item, ...data } : item);
    const result = await updateFile(`${allData.json.year}`, allData.json);
    if (result.status === "error")
      return { status: "error", error: result.error };
    return { status: "success" };
  } catch (error) {
    return { status: "error", error: error instanceof Error ? error : new Error(`Failed to editing JSON to history: ${String(error)}`) };
  }
};
var editingJsonToPlan = async (data) => {
  const allCategories = await getAllFile("categories");
  if (allCategories.status === "error")
    return { status: "error", error: allCategories.error };
  try {
    const plan = data.type === "expense" ? allCategories.json.categories.expenditure_plan : allCategories.json.categories.income_plan;
    const updatedPlan = plan.map((item) => item.id === data.id ? { ...item, ...data } : item);
    if (data.type === "expense") {
      allCategories.json.categories.expenditure_plan = updatedPlan;
    } else if (data.type === "income") {
      allCategories.json.categories.income_plan = updatedPlan;
    } else {
      return { status: "error", error: new Error("The specified type is not suitable") };
    }
    const result = await updateFile("categories", allCategories.json);
    if (result.status === "error")
      return { status: "error", error: result.error };
    return { status: "success" };
  } catch (error) {
    return { status: "error", error: error instanceof Error ? error : new Error(`Failed to editing JSON to plan: ${String(error)}`) };
  }
};
